    for (var i = 0; i < 5 + ((rng() * 3) | 0); i++) FA.sp.birds.push({ x: hx + (rng() - 0.5) * 2.4, z: hz + (rng() - 0.5) * 1.4, y: 0, face: rng() < 0.5 ? 1 : -1, act: 'peck', at: rng(), ph: rng() * TAU, vx: 0, vy: 0, vz: 0 });
